src/adapters/BridgeAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {IBridgeAdapter} from "../interfaces/IBridgeAdapter.sol";
import {IInboxCallback} from "../interfaces/IInboxCallback.sol";

/// @title BridgeAdapter
/// @author Agustin Aguilar
/// @notice Base contract for adapters that bridge assets from a PDA inbox
abstract contract BridgeAdapter is IBridgeAdapter {
  struct BridgeRouteTarget {
    bool supported;
    address tokenOut;
  }

  error TokenApprovalFailed(address _token);

  mapping(bytes32 routeKey => BridgeRouteTarget target) private bridgeRouteTargets;

  function supportsBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    public
    view
    virtual
    returns (bool _supported)
  {
    BridgeRouteTarget storage target = bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)];
    return target.supported && target.tokenOut == _tokenOut;
  }

  function _executeInboxTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bytes memory _result)
  {
    return IInboxCallback(msg.sender).executeBridgeInboxTransaction(_inbox, _target, _value, _data);
  }

  function _addressToBytes32(address _addr) internal pure returns (bytes32) {
    return bytes32(uint256(uint160(_addr)));
  }

  function _inboxAssetBalance(address _inbox, address _token) internal view returns (uint256) {
    if (_token == address(0)) {
      return _inbox.balance;
    }

    return IERC20(_token).balanceOf(_inbox);
  }

  function _resolveAmountIn(uint256 _amountIn, uint256 _balance) internal pure returns (uint256) {
    return _amountIn == 0 ? _balance : _amountIn;
  }

  function _setInboxTokenApproval(address _inbox, address _token, address _spender, uint256 _amount) internal {
    bytes memory result =
      _executeInboxTransaction(_inbox, _token, 0, abi.encodeCall(IERC20.approve, (_spender, _amount)));
    if (result.length != 0 && !abi.decode(result, (bool))) {
      revert TokenApprovalFailed(_token);
    }
  }

  function _setBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId) internal {
    bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)] =
      BridgeRouteTarget({supported: true, tokenOut: _tokenOut});
  }

  function _clearBridgeRoute(address _tokenIn, uint256 _dstChainId) internal {
    delete bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)];
  }

  function _bridgeRouteKey(address _tokenIn, uint256 _dstChainId) private pure returns (bytes32) {
    return keccak256(abi.encode(_tokenIn, _dstChainId));
  }
}

src/adapters/HyperlaneAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

import {BridgeAdapter} from "./BridgeAdapter.sol";
import {BridgeExecution, BridgeFee, BridgeQuote} from "../interfaces/IBridgeAdapter.sol";
import {
  HypTokenQuote,
  IHypTokenRouter,
  IHypTokenRouterScale,
  ILegacyHypTokenRouterScale
} from "../interfaces/IHypTokenRouter.sol";

/// @title HyperlaneAdapter
/// @author Agustin Aguilar
/// @notice Bridge adapter for standard fungible Hyperlane TokenRouter transfers from an inbox
/// @dev Hyperlane warp routes deliver the dispatched value without bridge slippage, but source and
///      destination routers may express that value in different token denominations. The adapter
///      reproduces Hyperlane's source-local -> message -> destination-local scale conversions and
///      reports the destination-local amount as `amountOut`. This is the explicit bridge-adapter
///      trust boundary: the route's delivery guarantee is the warp route's, enforced by its
///      Interchain Security Module rather than by this adapter.
///
///      This adapter supports standard fungible `HypERC20`, `HypERC20Collateral`, and `HypNative`
///      routers whose amount conversion is defined by the TokenRouter scale getters. Routers that
///      override amount conversion dynamically (for example ERC-4626 share routes), NFT routes,
///      and other custom bridges require a dedicated adapter.
///
///      What the adapter must NOT assume is the input side. A warp route with an owner-set
///      `feeRecipient` debits `amount + fee` from the caller while still dispatching `amount`, so
///      `execute` reports the inbox debit it MEASURES around `transferRemote` rather than the amount
///      it requested. Route accounting snapshots the inbox again after the bridge call and reverts
///      with `BridgeDebitMismatch` when a declared asset lost more than the quote reports
///      (`RouteAccounting._validateBridgeRoute`), so an unreported additive fee cannot escape the
///      slippage floor; measuring here is defense in depth, and it is also what keeps those routes
///      executable. Modern routers expose the expected debit through `quoteTransferRemote`;
///      legacy routers fall back to `quoteGasPayment`. Execution still measures the actual token
///      and native debits so the returned quote remains authoritative.
contract HyperlaneAdapter is BridgeAdapter, Ownable {
  struct Destination {
    address router;
    address tokenOut;
    uint32 dstDomain;
    uint256 sourceScaleNumerator;
    uint256 sourceScaleDenominator;
    uint256 remoteScaleNumerator;
    uint256 remoteScaleDenominator;
  }

  struct TransferReceipt {
    uint256 amountIn;
    uint256 amountDebited;
    uint256 amountOut;
    uint256 gasPayment;
    uint32 dstDomain;
    bytes32 recipient;
  }

  mapping(address tokenIn => mapping(uint256 dstChainId => Destination destination)) public destinations;

  event DestinationSet(
    address indexed _tokenIn,
    uint256 indexed _dstChainId,
    address indexed _tokenOut,
    address _router,
    uint32 _dstDomain,
    uint256 _sourceScaleNumerator,
    uint256 _sourceScaleDenominator,
    uint256 _remoteScaleNumerator,
    uint256 _remoteScaleDenominator
  );
  event DestinationCleared(address indexed _tokenIn, uint256 indexed _dstChainId);
  /// @param _amountIn Source-local amount passed to `transferRemote`.
  /// @param _amountDebited Measured `_tokenIn` debit of the inbox; exceeds `_amountIn` by any
  /// additive warp-route and native fee.
  /// @param _amountOut Expected destination-local amount after both Hyperlane scale conversions.
  /// @param _gasPayment Measured native debit reported as the quote's sole `BridgeFee`. For native
  /// routes this is every debit above `_amountIn`, including any additive native route fee.
  event HyperlaneTransferStarted(
    bytes32 indexed _operationId,
    address indexed _inbox,
    address indexed _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _amountDebited,
    uint256 _amountOut,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    uint256 _gasPayment,
    uint32 _dstDomain
  );

  error ZeroAddress();
  error InvalidAmount();
  error InvalidRecipient();
  error UnsupportedDestination(address _tokenIn, uint256 _dstChainId);
  error InvalidBridgeToken(address _expected, address _actual);
  error InvalidTokenOut(address _expected, address _actual);
  error InsufficientAmountOut(uint256 _expected, uint256 _actual);
  error UnexpectedTokenDebit(uint256 _dispatched, uint256 _debited);
  error UnsupportedQuoteToken(address _token);
  error InvalidRouterScale(address _router, uint256 _numerator, uint256 _denominator);
  error RouterScaleChanged(
    address _router,
    uint256 _expectedNumerator,
    uint256 _expectedDenominator,
    uint256 _actualNumerator,
    uint256 _actualDenominator
  );

  constructor(address _owner) Ownable(_owner) {}

  /// @notice Sets Hyperlane warp route metadata for a destination chain.
  /// @dev `_tokenIn` is the asset held by the inbox: the underlying ERC20 for collateral routes,
  ///      the synthetic token (the router itself) for synthetic routes, or `address(0)` for native
  ///      routes. An implemented `token()` must agree with `_tokenIn`; pre-scale HypNative routers
  ///      that predate that selector are accepted only for native input.
  ///
  ///      `_remoteScaleNumerator` and `_remoteScaleDenominator` must equal the destination
  ///      TokenRouter's scale getters. Hyperlane first rounds the source-local amount into message
  ///      units using the source router's scale, then rounds message units into destination-local
  ///      units using the inverse remote scale. Both stages are retained so denomination dust
  ///      cannot make the adapter overstate destination output.
  ///
  ///      The owner must source the remote scale from the enrolled destination router. It is remote
  ///      chain state and cannot be authenticated by this source-chain contract. The owner must
  ///      also ensure both routers use TokenRouter's standard scale-based amount conversion.
  ///      Custom routers expose the same public selectors, so this invariant cannot be inferred
  ///      from the shared TokenRouter ABI.
  function setDestination(
    address _tokenIn,
    address _router,
    uint256 _dstChainId,
    address _tokenOut,
    uint32 _dstDomain,
    uint256 _remoteScaleNumerator,
    uint256 _remoteScaleDenominator
  ) external onlyOwner {
    if (_router == address(0)) {
      revert ZeroAddress();
    }
    if (_dstChainId == 0 || _dstDomain == 0) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }

    address expectedToken = _tokenIn == address(0) ? address(0) : _tokenIn;
    _validateRouterToken(_router, expectedToken);

    if (_remoteScaleNumerator == 0 || _remoteScaleDenominator == 0) {
      revert InvalidRouterScale(_router, _remoteScaleNumerator, _remoteScaleDenominator);
    }
    (uint256 sourceScaleNumerator, uint256 sourceScaleDenominator) = _routerScale(_router);

    destinations[_tokenIn][_dstChainId] = Destination({
      router: _router,
      tokenOut: _tokenOut,
      dstDomain: _dstDomain,
      sourceScaleNumerator: sourceScaleNumerator,
      sourceScaleDenominator: sourceScaleDenominator,
      remoteScaleNumerator: _remoteScaleNumerator,
      remoteScaleDenominator: _remoteScaleDenominator
    });
    _setBridgeRoute(_tokenIn, _tokenOut, _dstChainId);

    emit DestinationSet(
      _tokenIn,
      _dstChainId,
      _tokenOut,
      _router,
      _dstDomain,
      sourceScaleNumerator,
      sourceScaleDenominator,
      _remoteScaleNumerator,
      _remoteScaleDenominator
    );
  }

  /// @notice Clears Hyperlane warp route metadata for a destination chain.
  function clearDestination(address _tokenIn, uint256 _dstChainId) external onlyOwner {
    delete destinations[_tokenIn][_dstChainId];
    _clearBridgeRoute(_tokenIn, _dstChainId);

    emit DestinationCleared(_tokenIn, _dstChainId);
  }

  /// @notice Quotes a Hyperlane warp route transfer for an explicit non-zero input amount.
  /// @dev Modern routers expose all debits through `quoteTransferRemote`, including additive
  /// `feeRecipient` fees. Legacy routers fall back to the native-only `quoteGasPayment` estimate.
  /// `execute` always reports the measured debit rather than trusting either estimate.
  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external view override returns (BridgeQuote memory _quote) {
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    if (_amountIn == 0) {
      revert InvalidAmount();
    }
    return _preflightQuote(destination, _tokenIn, _recipient, _amountIn, _minAmountOut);
  }

  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external override returns (BridgeExecution memory _execution) {
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    (uint256 amountIn, BridgeQuote memory preflight) =
      _resolveTransfer(_inbox, _tokenIn, _amountIn, destination, _recipient, _minAmountOut);
    uint256 value = preflight.fees[0].amount;
    if (_tokenIn == address(0)) {
      value += preflight.amountIn;
    }

    // Collateral routes always pull the route token. Synthetic routes normally burn directly, but
    // a token-denominated fee hook separately pulls its fee via `transferFrom`; a detailed quote
    // exposes that case as a token debit above the dispatched amount.
    bool requiresApproval = _tokenIn != address(0) && (_tokenIn != destination.router || preflight.amountIn > amountIn);
    (_execution.operationId, _execution.quote) = _sendHyperlaneTransfer(
      _inbox,
      _tokenIn,
      destination.router,
      destination.dstDomain,
      _recipient,
      amountIn,
      preflight.amountOut,
      value,
      requiresApproval
    );

    TransferReceipt memory receipt = TransferReceipt({
      amountIn: amountIn,
      amountDebited: _tokenIn == address(0)
        ? _execution.quote.amountIn + _execution.quote.fees[0].amount
        : _execution.quote.amountIn,
      amountOut: _execution.quote.amountOut,
      gasPayment: _execution.quote.fees[0].amount,
      dstDomain: destination.dstDomain,
      recipient: _recipient
    });
    _emitTransferStarted(_execution.operationId, _inbox, _tokenIn, _tokenOut, _minAmountOut, _dstChainId, receipt);
  }

  function _emitTransferStarted(
    bytes32 _operationId,
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    TransferReceipt memory _receipt
  ) private {
    emit HyperlaneTransferStarted(
      _operationId,
      _inbox,
      _tokenIn,
      _tokenOut,
      _receipt.amountIn,
      _receipt.amountDebited,
      _receipt.amountOut,
      _minAmountOut,
      _dstChainId,
      _receipt.recipient,
      _receipt.gasPayment,
      _receipt.dstDomain
    );
  }

  function _validatedDestination(address _tokenIn, address _tokenOut, uint256 _dstChainId, bytes32 _recipient)
    private
    view
    returns (Destination storage destination)
  {
    destination = destinations[_tokenIn][_dstChainId];
    if (destination.router == address(0)) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (_tokenOut != destination.tokenOut) {
      revert InvalidTokenOut(destination.tokenOut, _tokenOut);
    }
    if (_recipient == bytes32(0)) {
      revert InvalidRecipient();
    }
  }

  /// @dev Uses the standardized modern Hyperlane quote when available. `quoteTransferRemote`
  ///      returns every debit, and may contain repeated native or route-token entries. The adapter
  ///      folds route-token fees into `amountIn` and keeps the existing single-native-fee shape.
  ///      Older routers that lack the selector fall back to their native gas quote.
  function _preflightQuote(
    Destination storage _destination,
    address _tokenIn,
    bytes32 _recipient,
    uint256 _amountIn,
    uint256 _minAmountOut
  ) private view returns (BridgeQuote memory _quote) {
    uint256 amountOut = _destinationAmount(_destination, _amountIn);
    if (amountOut == 0) {
      revert InvalidAmount();
    }
    if (amountOut < _minAmountOut) {
      revert InsufficientAmountOut(_minAmountOut, amountOut);
    }

    try IHypTokenRouter(_destination.router)
      .quoteTransferRemote(_destination.dstDomain, _recipient, _amountIn) returns (
      HypTokenQuote[] memory quotes
    ) {
      return _buildDetailedQuote(_tokenIn, _amountIn, amountOut, quotes);
    } catch {
      uint256 gasPayment = IHypTokenRouter(_destination.router).quoteGasPayment(_destination.dstDomain);
      return _buildLegacyQuote(_amountIn, amountOut, gasPayment);
    }
  }

  function _buildDetailedQuote(
    address _tokenIn,
    uint256 _amountIn,
    uint256 _amountOut,
    HypTokenQuote[] memory _routerQuotes
  ) private pure returns (BridgeQuote memory _quote) {
    uint256 nativeDebit;
    uint256 tokenDebit;
    for (uint256 i = 0; i < _routerQuotes.length; i++) {
      HypTokenQuote memory routerQuote = _routerQuotes[i];
      if (routerQuote.amount == 0) {
        continue;
      }
      if (routerQuote.token == address(0)) {
        nativeDebit += routerQuote.amount;
      } else if (_tokenIn != address(0) && routerQuote.token == _tokenIn) {
        tokenDebit += routerQuote.amount;
      } else {
        revert UnsupportedQuoteToken(routerQuote.token);
      }
    }

    BridgeFee[] memory fees = new BridgeFee[](1);
    if (_tokenIn == address(0)) {
      if (nativeDebit < _amountIn) {
        revert UnexpectedTokenDebit(_amountIn, nativeDebit);
      }
      fees[0] = BridgeFee({token: address(0), amount: nativeDebit - _amountIn});
      return BridgeQuote({amountIn: _amountIn, amountOut: _amountOut, fees: fees});
    }

    if (tokenDebit < _amountIn) {
      revert UnexpectedTokenDebit(_amountIn, tokenDebit);
    }
    fees[0] = BridgeFee({token: address(0), amount: nativeDebit});
    return BridgeQuote({amountIn: tokenDebit, amountOut: _amountOut, fees: fees});
  }

  /// @dev Legacy pre-execution estimate. The output amount still uses the configured Hyperlane
  ///      source and destination scales; the quoted interchain gas is the sole visible fee.
  function _buildLegacyQuote(uint256 _amountIn, uint256 _amountOut, uint256 _gasPayment)
    private
    pure
    returns (BridgeQuote memory _quote)
  {
    BridgeFee[] memory fees = new BridgeFee[](1);
    fees[0] = BridgeFee({token: address(0), amount: _gasPayment});

    _quote = BridgeQuote({amountIn: _amountIn, amountOut: _amountOut, fees: fees});
  }

  /// @dev Resolves the dispatched amount and its final preflight quote. For a full-balance transfer,
  ///      first quotes the entire balance to discover fees paid in the route asset, then reserves
  ///      those fees before quoting the reduced dispatch amount. This keeps both native and ERC-20
  ///      fee-bearing routes within the inbox balance. Legacy ERC-20 routers cannot expose an
  ///      additive route-token fee, so their full-balance behavior remains limited by their quote.
  function _resolveTransfer(
    address _inbox,
    address _tokenIn,
    uint256 _amountIn,
    Destination storage _destination,
    bytes32 _recipient,
    uint256 _minAmountOut
  ) private view returns (uint256 _resolvedAmountIn, BridgeQuote memory _quote) {
    if (_amountIn != 0) {
      _resolvedAmountIn = _amountIn;
      _quote = _preflightQuote(_destination, _tokenIn, _recipient, _resolvedAmountIn, _minAmountOut);
      return (_resolvedAmountIn, _quote);
    }

    uint256 balance = _inboxAssetBalance(_inbox, _tokenIn);
    if (balance == 0) {
      revert InvalidAmount();
    }

    BridgeQuote memory fullBalanceQuote = _preflightQuote(_destination, _tokenIn, _recipient, balance, 0);
    uint256 fullBalanceDebit = _quotedRouteAssetDebit(_tokenIn, fullBalanceQuote);
    uint256 routeAssetFees = fullBalanceDebit - balance;
    if (balance <= routeAssetFees) {
      revert InvalidAmount();
    }

    _resolvedAmountIn = balance - routeAssetFees;
    _quote = _preflightQuote(_destination, _tokenIn, _recipient, _resolvedAmountIn, _minAmountOut);

    // Standard Hyperlane fee models are monotonic, so quoting the lower amount cannot increase its
    // fee. Retain an explicit bound in case a custom fee recipient violates that expectation.
    if (_quotedRouteAssetDebit(_tokenIn, _quote) > balance) {
      revert InvalidAmount();
    }
  }

  function _quotedRouteAssetDebit(address _tokenIn, BridgeQuote memory _quote)
    private
    pure
    returns (uint256 _routeAssetDebit)
  {
    return _tokenIn == address(0) ? _quote.amountIn + _quote.fees[0].amount : _quote.amountIn;
  }

  /// @dev Dispatches the transfer and reports the inbox debits it actually caused.
  function _sendHyperlaneTransfer(
    address _inbox,
    address _tokenIn,
    address _router,
    uint32 _dstDomain,
    bytes32 _recipient,
    uint256 _amountIn,
    uint256 _amountOut,
    uint256 _value,
    bool _requiresApproval
  ) private returns (bytes32 _operationId, BridgeQuote memory _quote) {
    uint256 nativeBefore = _inbox.balance;
    uint256 tokenBefore = _tokenIn == address(0) ? 0 : _inboxAssetBalance(_inbox, _tokenIn);

    // The approval is unbounded because routes with an owner-set `feeRecipient` pull
    // `amount + fee` (the fee is additive on top of the bridged amount); it is reset to zero
    // immediately after the call, and whatever the route took is measured rather than assumed.
    if (_requiresApproval) {
      _setInboxTokenApproval(_inbox, _tokenIn, _router, type(uint256).max);
    }

    bytes memory result = _executeInboxTransaction(
      _inbox, _router, _value, abi.encodeCall(IHypTokenRouter.transferRemote, (_dstDomain, _recipient, _amountIn))
    );

    if (_requiresApproval) {
      _setInboxTokenApproval(_inbox, _tokenIn, _router, 0);
    }

    _operationId = abi.decode(result, (bytes32));
    _quote = _measuredQuote(_inbox, _tokenIn, _amountIn, _amountOut, tokenBefore, nativeBefore);
  }

  /// @dev Builds the route quote from the inbox balances `transferRemote` actually consumed, so an
  ///      additive warp-route fee is charged against the route's slippage budget instead of
  ///      disappearing. Reported debits are only ever >= the request, never less, and any native
  ///      refund of an over-quoted gas payment lowers the reported fee accordingly.
  function _measuredQuote(
    address _inbox,
    address _tokenIn,
    uint256 _amountIn,
    uint256 _amountOut,
    uint256 _tokenBefore,
    uint256 _nativeBefore
  ) private view returns (BridgeQuote memory _quote) {
    uint256 nativeDebit = _debit(_nativeBefore, _inbox.balance);
    BridgeFee[] memory fees = new BridgeFee[](1);

    if (_tokenIn == address(0)) {
      // Native routes pay the bridged amount and the interchain gas out of one balance: the
      // dispatched amount is the input and the rest of the debit is the fee.
      if (nativeDebit < _amountIn) {
        revert UnexpectedTokenDebit(_amountIn, nativeDebit);
      }

      fees[0] = BridgeFee({token: address(0), amount: nativeDebit - _amountIn});
      return BridgeQuote({amountIn: _amountIn, amountOut: _amountOut, fees: fees});
    }

    uint256 tokenDebit = _debit(_tokenBefore, _inboxAssetBalance(_inbox, _tokenIn));
    if (tokenDebit < _amountIn) {
      revert UnexpectedTokenDebit(_amountIn, tokenDebit);
    }

    fees[0] = BridgeFee({token: address(0), amount: nativeDebit});
    return BridgeQuote({amountIn: tokenDebit, amountOut: _amountOut, fees: fees});
  }

  function _debit(uint256 _before, uint256 _after) private pure returns (uint256) {
    return _after >= _before ? 0 : _before - _after;
  }

  /// @dev Reproduces Hyperlane's two separately-rounded denomination conversions:
  ///      source-local -> message using the source scale, then message -> destination-local using
  ///      the inverse remote scale. Combining the fractions would incorrectly restore source-side
  ///      dust when the destination scale expands the message amount.
  function _destinationAmount(Destination storage _destination, uint256 _sourceAmount)
    private
    view
    returns (uint256 _amountOut)
  {
    (uint256 actualNumerator, uint256 actualDenominator) = _routerScale(_destination.router);
    if (
      actualNumerator != _destination.sourceScaleNumerator || actualDenominator != _destination.sourceScaleDenominator
    ) {
      revert RouterScaleChanged(
        _destination.router,
        _destination.sourceScaleNumerator,
        _destination.sourceScaleDenominator,
        actualNumerator,
        actualDenominator
      );
    }

    uint256 messageAmount =
      Math.mulDiv(_sourceAmount, _destination.sourceScaleNumerator, _destination.sourceScaleDenominator);
    return Math.mulDiv(messageAmount, _destination.remoteScaleDenominator, _destination.remoteScaleNumerator);
  }

  function _routerScale(address _router) private view returns (uint256 _numerator, uint256 _denominator) {
    (bool numeratorFound, uint256 numerator) = _readOptionalUint(_router, IHypTokenRouterScale.scaleNumerator.selector);
    (bool denominatorFound, uint256 denominator) =
      _readOptionalUint(_router, IHypTokenRouterScale.scaleDenominator.selector);

    if (numeratorFound || denominatorFound) {
      if (!numeratorFound || !denominatorFound || numerator == 0 || denominator == 0) {
        revert InvalidRouterScale(_router, numerator, denominator);
      }
      return (numerator, denominator);
    }

    (bool legacyScaleFound, uint256 legacyScale) = _readOptionalUint(_router, ILegacyHypTokenRouterScale.scale.selector);
    if (legacyScaleFound) {
      if (legacyScale == 0) {
        revert InvalidRouterScale(_router, legacyScale, 1);
      }
      return (legacyScale, 1);
    }

    // Routers predating Hyperlane's scale field dispatched amounts 1:1.
    return (1, 1);
  }

  /// @dev Pre-scale HypNative deployments predate the `token()` selector. Treat a missing selector
  ///      as native only when the configured inbox asset is native; ERC-20 routes must still prove
  ///      their underlying token, and any implemented selector must return the expected asset.
  function _validateRouterToken(address _router, address _expectedToken) private view {
    if (_router.code.length == 0) {
      revert InvalidBridgeToken(_expectedToken, address(0));
    }

    (bool success, bytes memory result) = _router.staticcall(abi.encodeCall(IHypTokenRouter.token, ()));
    if (!success || result.length == 0) {
      if (_expectedToken != address(0)) {
        revert InvalidBridgeToken(_expectedToken, address(0));
      }
      return;
    }
    if (result.length != 32) {
      revert InvalidBridgeToken(_expectedToken, address(0));
    }

    address routerToken = abi.decode(result, (address));
    if (routerToken != _expectedToken) {
      revert InvalidBridgeToken(_expectedToken, routerToken);
    }
  }

  function _readOptionalUint(address _target, bytes4 _selector) private view returns (bool _found, uint256 _value) {
    (bool success, bytes memory result) = _target.staticcall(abi.encodeWithSelector(_selector));
    if (!success || result.length == 0) {
      return (false, 0);
    }
    if (result.length != 32) {
      revert InvalidRouterScale(_target, 0, 0);
    }
    return (true, abi.decode(result, (uint256)));
  }
}

src/interfaces/IBridgeAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

struct BridgeFee {
  address token;
  uint256 amount;
}

struct BridgeQuote {
  uint256 amountIn;
  uint256 amountOut;
  BridgeFee[] fees;
}

struct BridgeExecution {
  bytes32 operationId;
  BridgeQuote quote;
}

/// @title IBridgeAdapter
/// @author Agustin Aguilar
/// @notice Interface for adapters that bridge assets from an inbox
interface IBridgeAdapter {
  /// @notice Returns whether the exact input token, output token, and destination chain route is supported.
  function supportsBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    external
    view
    returns (bool _supported);

  /// @notice Quotes a bridge operation for an explicit non-zero input amount.
  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external view returns (BridgeQuote memory _quote);

  /// @notice Executes a bridge operation from `_inbox`; `_amountIn == 0` uses the full inbox balance.
  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external returns (BridgeExecution memory _execution);
}

src/interfaces/IHypTokenRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

struct HypTokenQuote {
  address token;
  uint256 amount;
}

/// @title IHypTokenRouter
/// @author Agustin Aguilar
/// @notice Minimal Hyperlane warp route (TokenRouter) interface
/// @dev Covers the collateral (`HypERC20Collateral`), synthetic (`HypERC20`) and native
///      (`HypNative`) fungible variants. All three expose the same `transferRemote` entry point.
///      Vault-share, NFT, and custom routers that override the standard scale-based amount
///      conversion are outside this interface's supported semantics.
interface IHypTokenRouter {
  /// @notice The asset moved by this route.
  /// @dev Returns the underlying ERC20 for collateral routes, `address(this)` for synthetic
  ///      routes (the router is itself the ERC20), and `address(0)` for current native routes.
  ///      Pre-scale HypNative deployments may not implement this selector; the adapter accepts
  ///      that omission only when the configured input asset is native.
  function token() external view returns (address);

  /// @notice Quotes the native interchain gas payment for delivering a message to `_destination`.
  /// @dev Amount-independent: priced from the route's per-destination gas limit. Does not include
  ///      a non-zero Mailbox `ProtocolFee` (the `requiredHook`), which is zero on supported chains.
  function quoteGasPayment(uint32 _destination) external view returns (uint256 _gasPayment);

  /// @notice Quotes every asset the router will debit for a transfer.
  /// @dev Modern TokenRouter deployments return native dispatch fees, the bridged amount plus any
  ///      internal `feeRecipient` fee, and any external route fee. Legacy routers may not implement
  ///      this selector; the adapter falls back to `quoteGasPayment` for those deployments.
  function quoteTransferRemote(uint32 _destination, bytes32 _recipient, uint256 _amount)
    external
    view
    returns (HypTokenQuote[] memory _quotes);

  /// @notice Locks/burns `_amount` of `token()` from the caller and dispatches a transfer to
  ///         `_recipient` on `_destination`. Native messaging fee is paid via attached value.
  /// @return _messageId The Hyperlane message id, used as the bridge operation id.
  function transferRemote(uint32 _destination, bytes32 _recipient, uint256 _amount)
    external
    payable
    returns (bytes32 _messageId);
}

/// @notice Scale interface used by current Hyperlane TokenRouter deployments.
interface IHypTokenRouterScale {
  function scaleNumerator() external view returns (uint256 _scaleNumerator);

  function scaleDenominator() external view returns (uint256 _scaleDenominator);
}

/// @notice Scale interface used by Hyperlane TokenRouter v10 and earlier deployments.
interface ILegacyHypTokenRouterScale {
  function scale() external view returns (uint256 _scale);
}

